import re, json
with open('/tmp/repo.html') as f:
    html = f.read()

# Try to find JSON embedded in the page (React data)
scripts = re.findall(r'<script[^>]*>(.*?)</script>', html, re.DOTALL)
for i, s in enumerate(scripts):
    if 'ore-ero-fr' in s and len(s) > 1000:
        print('--- script', i, len(s))
        # Look for specific JSON objects
        if 'language' in s[:1000]:
            print(s[:500])
        break

# Also search for specific aria-label patterns
for pat in [r'aria-label=\"([^\"]+)\"', r'data-testid=\"([^\"]+)\"', r'title=\"([^\"]+)\"']:
    matches = re.findall(pat, html)
    for m in matches:
        if any(k in m.lower() for k in ['issue', 'commit', 'language', 'license', 'contributing', 'readme', 'dependabot']):
            print(pat, m)
"

