import re, json
with open('/tmp/repo.html') as f:
    html = f.read()

# Search for JSON script tags
scripts = re.findall(r'<script[^>]*>(.*?)</script>', html, re.DOTALL)
for i, s in enumerate(scripts):
    if len(s) > 1000:
        # Try to find JSON objects with specific keys
        if 'language' in s or 'issues' in s or 'license' in s or 'commits' in s:
            print(f'--- script {i} len={len(s)} ---')
            # Try to extract a JSON object
            try:
                # Look for JSON objects starting with { or [
                if s.strip().startswith('{') or s.strip().startswith('['):
                    data = json.loads(s.strip()[:10000])
                    print(json.dumps(data, indent=2)[:1000])
            except Exception as e:
                # Look for JSON in the text
                json_matches = re.findall(r'\{[^{}]*\"language\"[^{}]*\}', s)
                if json_matches:
                    for jm in json_matches[:3]:
                        print('JSON match:', jm[:200])
                else:
                    print(s[:200])
            print()
"

