import re, json
with open('/tmp/repo_tree.html') as f:
    html = f.read()

m = re.search(r'<script type=\"application/json\" data-target=\"react-app.embeddedData\">(.*?)</script>', html, re.DOTALL)
if m:
    data = json.loads(m.group(1))
    tree_items = data['payload']['codeViewRepoRoute']['tree']['items']
    for item in tree_items:
        if item['contentType'] == 'directory' and item['name'] == '.github':
            print('Found .github directory')
        elif 'dependabot' in item['name'].lower() or 'renovate' in item['name'].lower():
            print('Found dependency config:', item['name'])
        else:
            print('File/Dir:', item['name'])
"

