import re, json
with open('/tmp/issues_embedded.html') as f:
    html = f.read()

scripts = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', html, re.DOTALL)
for i, s in enumerate(scripts):
    try:
        d = json.loads(s)
        if isinstance(d, dict) and 'payload' in d and 'preloaded_records' in d['payload']:
            print(f'Script {i}: preloaded_records keys={list(d[\"payload\"][\"preloaded_records\"].keys())}')
            # Look for issue data
            if 'issues' in d['payload']['preloaded_records']:
                issues = d['payload']['preloaded_records']['issues']
                print(f'Issues count: {len(issues) if isinstance(issues, list) else \"not list\"}')
                if isinstance(issues, list):
                    for issue in issues[:5]:
                        print('Issue:', issue.get('title', 'N/A'), 'state:', issue.get('state', 'N/A'))
            # Also look for 'data' or 'nodes'
            if 'data' in d['payload']['preloaded_records']:
                data = d['payload']['preloaded_records']['data']
                print('Data type:', type(data))
                if isinstance(data, list) and len(data) > 0:
                    print('First item:', json.dumps(data[0], indent=2)[:500])
    except Exception as e:
        print(f'Script {i} error: {e}')
"

